// Real renderer interactions with in-memory bridge responses; no desktop or network operations.
export default async function managementScenarios(review) {
  await review.waitFor('window.__modelReview?.ready === true');
  await review.viewport(1440, 1000);
  await review.evaluate(`(() => {
    const fixture = window.__modelReview, bridge = window.piDesktop;
    const clone = value => structuredClone(value);
    const cwd = fixture.snapshot.cwd, second = 'C:/renderer-review/second-project';
    const firstPath = fixture.snapshot.sessionPath, secondPath = 'C:/renderer-review/second.jsonl';
    const item = (path, name) => ({path,id:path,name,firstMessage:name,modified:'2026-09-26T08:00:00Z',messageCount:3});
    const state = {cwd,second,firstPath,secondPath,failWorkspace:true,rows:{[cwd]:[item(firstPath,'后台审查会话'),item(secondPath,'当前编辑会话')],[second]:[]},deletes:[],saves:[],copied:[],pendingDelete:null};
    bridge.listWorkspaces = async () => [cwd,second];
    bridge.listSessions = async path => { if (path === second && state.failWorkspace) throw new Error('模拟项目列表读取失败'); return clone(state.rows[path] || []); };
    bridge.switchSession = async path => {
      Object.assign(fixture.snapshot,{sessionPath:path,sessionId:path,status:'idle',error:null});
      fixture.emitAgent({type:'reset',cwd}); fixture.emitAgent({type:'ready',...clone(fixture.snapshot)}); fixture.emitAgent({type:'status',status:'idle'});
    };
    bridge.updateSessionMeta = async (path,patch) => { Object.assign(Object.values(state.rows).flat().find(row=>row.path===path),patch); };
    bridge.deleteSession = async path => { state.deletes.push(path); return new Promise((resolve,reject)=>{state.pendingDelete={resolve,reject,path};}); };
    state.rejectDelete = () => { const pending=state.pendingDelete;state.pendingDelete=null;pending.reject(new Error('模拟回收站暂时不可写')); };
    state.finishDelete = () => { const pending=state.pendingDelete;state.pendingDelete=null;for(const path of Object.keys(state.rows))state.rows[path]=state.rows[path].filter(row=>row.path!==pending.path);pending.resolve(); };
    state.runtime = (path,phase,message) => { const row=state.rows[cwd].find(entry=>entry.path===path);if(row)row.runtime={phase,message};fixture.emitAgent({type:'session-runtime',cwd,path,runtime:{phase,message}}); };
    const task={id:'review-task',name:'每日项目审查',prompt:'检查项目并整理需要处理的问题',cwd,model:{provider:'openai',id:'gpt-review'},thinkingLevel:'high',schedule:{kind:'weekly',days:[1,2,3,4,5],time:'09:00'},timeZone:'Asia/Shanghai',enabled:true,createdAt:'2026-09-20T00:00:00Z',updatedAt:'2026-09-25T00:00:00Z',nextRunAt:'2026-09-28T01:00:00Z',lastRunAt:'2026-09-26T01:00:00Z'};
    const run=(id,status,date)=>({id,automationId:task.id,name:task.name,cwd,trigger:'schedule',status,startedAt:date,finishedAt:date,sessionId:secondPath,sessionPath:secondPath,summary:status==='failed'?'':'已完成检查',error:status==='failed'?'模拟模型服务暂时不可用':null});
    state.automations={revision:1,automations:[task],runs:[run('older-success','succeeded','2026-09-25T01:00:00Z'),run('latest-failure','failed','2026-09-26T01:00:00Z')]};
    bridge.getAutomationSnapshot=async()=>clone(state.automations);
    bridge.saveAutomation=async input=>{state.saves.push(clone(input));state.automations.revision++;state.automations.automations.push({...clone(input),id:'created-task',createdAt:'2026-09-26T00:00:00Z',updatedAt:'2026-09-26T00:00:00Z',lastRunAt:null,nextRunAt:null});return clone(state.automations);};
    const source='npm:renderer-review';
    state.catalog={cwd,projectTrusted:true,warnings:[],packages:[{source,scope:'user',name:'项目工作流插件',description:'包含30个扩展、技能、提示词与主题资源，用于验证分组浏览。',version:'1.0.0',installed:true,path:'C:/renderer-review/plugins'}],resources:Array.from({length:30},(_,i)=>({path:'C:/renderer-review/plugins/resources/'+i+'.md',kind:['extensions','skills','prompts','themes'][i%4],name:i===5?'broken-resource':('resource-'+String(i).padStart(2,'0')),description:'可复用的项目工作流能力，支持中文描述与长路径。',enabled:true,loaded:i!==5,canToggle:true,scope:'user',source,origin:'package',...(i===5?{error:'无法解析技能文件：请检查文档开头的元数据格式。'}:{})}))};
    bridge.getPluginCatalog=async()=>clone(state.catalog);
    bridge.previewPluginResource=async request=>({path:request.path,text:'# Resource preview',truncated:false});
    bridge.mutatePlugin=async input=>{state.lastPluginMutation=clone(input);const resource=state.catalog.resources.find(entry=>entry.path===input.path);if(resource)resource.enabled=input.enabled;return clone(state.catalog);};
    Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async text=>{state.copied.push(text);}}});
    window.__managementReview=state;
  })()`);
  await review.click('[data-mode="project"]');
  await review.click('.pd-sidebar-list-heading .pd-section-actions button:first-child');
  await review.waitFor("document.querySelectorAll('[data-session-path]').length===2 && Boolean(document.querySelector('.pd-workspace-list-error'))");
  await review.assert("!document.querySelector('.pd-workspace-list-error').textContent.includes('加载中')", 'Failed workspace stops loading and exposes a local retry');
  await review.evaluate('window.__managementReview.failWorkspace=false');
  await review.click('.pd-workspace-list-error button');
  await review.waitFor("!document.querySelector('.pd-workspace-list-error')");
  await review.evaluate("window.__managementReview.runtime(window.__managementReview.firstPath,'running')");
  await review.click('.pd-session-item:nth-child(2) .pd-session-row');
  await review.assert("document.querySelector('.pd-session-runtime.is-running')?.textContent==='运行中' && document.querySelector('.pd-session-item.is-active strong')?.textContent==='当前编辑会话'", 'A continues running after navigation to B');
  await review.evaluate("window.__managementReview.runtime(window.__managementReview.firstPath,'waiting-input','请选择要继续的分支')");
  await review.waitFor("Boolean(document.querySelector('.pd-session-runtime.is-waiting-input'))");
  await review.click('.pd-sidebar-group:first-child .pd-sidebar-group-toggle');
  await review.assert("document.querySelector('.pd-sidebar-group:first-child .pd-session-state-counts')?.getAttribute('aria-label').includes('待处理 1')", 'Collapsed project retains the runtime attention count');
  await review.screenshot('management-01-sidebar-runtime-dark');
  await review.click('.pd-sidebar-group:first-child .pd-sidebar-group-toggle');
  await review.evaluate("window.__managementReview.runtime(window.__managementReview.firstPath,'failed','模拟后台任务失败')");

  await review.click('.pd-session-item:first-child .pd-session-more');
  await review.click('.pd-sidebar-menu-danger');
  await review.waitFor("Boolean(document.querySelector('.pd-session-trash-dialog[open]'))");
  await review.assert("document.querySelector('.pd-session-trash-dialog').textContent.includes('后台审查会话') && document.querySelector('.pd-session-trash-workspace').textContent===window.__managementReview.cwd", 'Trash dialog retains the exact title and workspace');
  await review.key('Escape');
  await review.assert("!document.querySelector('.pd-session-trash-dialog') && window.__managementReview.deletes.length===0", 'Esc cancels without a deletion request');
  await review.click('.pd-session-item:first-child .pd-session-more');
  await review.click('.pd-sidebar-menu-danger');
  await review.click('.pd-session-trash-dialog button.is-danger');
  await review.key('Enter');
  await review.assert("document.querySelector('.pd-session-trash-dialog button.is-danger').disabled && window.__managementReview.deletes.length===1", 'Repeated activation while deleting submits only once');
  await review.evaluate('window.__managementReview.rejectDelete()');
  await review.waitFor("Boolean(document.querySelector('.pd-session-trash-error'))");
  await review.screenshot('management-02-trash-retry');
  await review.click('.pd-session-trash-dialog button.is-danger');
  await review.evaluate('window.__managementReview.finishDelete()');
  await review.waitFor("!document.querySelector('.pd-session-trash-dialog') && document.querySelectorAll('[data-session-path]').length===1");
  await review.record('trash-restored-focus', "({activeTag:document.activeElement.tagName,activeClass:document.activeElement.className,activePath:document.activeElement.closest('[data-session-path]')?.dataset.sessionPath,deletes:window.__managementReview.deletes,target:window.__managementReview.firstPath})");
  await review.assert("document.activeElement.matches('.pd-session-row,.pd-organized-list') && window.__managementReview.deletes.every(path=>path===window.__managementReview.firstPath)", 'Retry preserves its target and success restores list focus');

  await review.click('.pd-sidebar-automation');
  await review.waitFor("Boolean(document.querySelector('.pd-automation-latest'))");
  await review.assert("document.querySelector('.pd-automation-card-heading .pd-automation-status').textContent.includes('已启用') && document.querySelector('.pd-automation-latest').textContent.includes('失败')", 'Enabled schedule and latest failed result are both visible');
  await review.click('.pd-automation-latest');
  await review.waitFor("document.activeElement.dataset.runId==='latest-failure'");
  await review.fill('.pd-automation-history-filter select', 'succeeded');
  await review.assert("document.querySelectorAll('.pd-automation-run').length===1 && document.querySelector('.pd-automation-run').dataset.runId==='older-success'", 'History result filter selects the matching run');
  await review.key('Escape');
  await review.click('.pd-automation-intro > button');
  await review.assert("!document.querySelector('.pd-automation-model-options').open && document.querySelector('.pd-automation-schedule-summary').textContent.includes(Intl.DateTimeFormat().resolvedOptions().timeZone)", 'Default editor hides model details and continuously shows its timezone');
  await review.fill('.pd-automation-editor-section:first-child input', '默认模型任务');
  await review.fill('.pd-automation-editor-section:first-child textarea', '整理今天的项目变更');
  await review.click('.pd-automation-dialog button[type="submit"]');
  await review.waitFor("window.__managementReview.saves.length===1 && !document.querySelector('.pd-automation-dialog')");
  await review.assert('window.__managementReview.saves[0].model===null && window.__managementReview.saves[0].thinkingLevel===null', 'Default task saves without requiring model configuration');
  await review.click('.pd-automation-card:first-child .pd-automation-card-heading button');
  await review.assert("document.querySelector('.pd-automation-model-options').open && document.querySelector('.pd-automation-model-options summary').textContent.includes('GPT Review')", 'Editing a nondefault model expands and summarizes the saved configuration');
  await review.viewport(680, 720);
  await review.evaluate("document.documentElement.dataset.theme='light';document.documentElement.style.setProperty('--pd-ui-font-size','20px')");
  await review.screenshot('management-03-automation-editor-narrow-light-20px');
  await review.assert("document.querySelector('.pd-automation-dialog').getBoundingClientRect().bottom<=innerHeight && document.querySelector('.pd-automation-dialog footer button[type=submit]').getClientRects().length>0", 'Short narrow editor keeps its save action visible');
  await review.key('Escape');
  await review.viewport(1440, 1000);
  await review.evaluate("document.documentElement.dataset.theme='dark';document.documentElement.style.setProperty('--pd-ui-font-size','13px')");

  await review.click('.pd-sidebar-plugins');
  await review.waitFor("Boolean(document.querySelector('.pd-plugin-card-main'))");
  await review.click('.pd-plugin-card-main');
  await review.assert("document.querySelectorAll('.pd-plugin-resource-group').length===4 && document.querySelectorAll('.pd-plugin-resource').length===30 && document.querySelector('.pd-plugin-resource-group.has-error h3 button').getAttribute('aria-expanded')==='true'", 'Thirty resources are grouped with the error group expanded');
  await review.click('.pd-plugin-resource-group:first-child h3 button');
  await review.assert("document.querySelector('.pd-plugin-resource-group:first-child .pd-plugin-resources').hidden", 'Normal capability group can collapse');
  await review.fill('.pd-plugin-detail-search input', 'resource-00');
  await review.assert("document.querySelector('.pd-plugin-resource-group:first-child h3 button').getAttribute('aria-expanded')==='true' && document.querySelectorAll('.pd-plugin-resource').length===1", 'A search match automatically expands its group');
  await review.fill('.pd-plugin-detail-search input', 'broken-resource');
  await review.assert("document.querySelector('.pd-plugin-resource-group.has-error h3 button').getAttribute('aria-expanded')==='true' && document.querySelector('.pd-plugin-resource-status.is-error').getClientRects().length>0", 'Filtered error stays readable outside collapsed content');
  await review.click('.pd-plugin-resource-path summary');
  await review.click('.pd-plugin-resource-path button');
  await review.assert("window.__managementReview.copied.at(-1)===document.querySelector('.pd-plugin-resource-path code').textContent", 'Copy uses the exact resource path');
  await review.click('.pd-plugin-resource-actions button[role="switch"]');
  await review.waitFor("window.__managementReview.lastPluginMutation?.enabled===false");
  await review.assert("window.__managementReview.lastPluginMutation.path===window.__managementReview.copied.at(-1)", 'Resource toggle retains the selected resource identity');
  await review.screenshot('management-04-plugin-error-group-dark');
  await review.viewport(680, 800);
  await review.evaluate("document.documentElement.dataset.theme='light';document.documentElement.style.setProperty('--pd-ui-font-size','20px')");
  await review.screenshot('management-05-plugin-narrow-light-20px');
}
